550	function buildSessions() {
551	  const grid = document.getElementById('sessionGrid');
552	  const select = document.getElementById('regSession');
553	  let n = 0;
554	  SESSION_DATES.forEach(d => {
555	    d.slots.forEach(s => {
556	      n++;
557	      const t = SLOTS[s];
558	      const isTBD = s === 'TBD';
559	      const sessionLabel = isTBD ? `${d.label} 時間確認後公告` : `${d.label} ${t.start}–${t.end}`;
560	      const card = document.createElement('div');
561	      card.className = 'session-card bg-white rounded-2xl p-6';
562	      card.innerHTML = `
563	        <div class="text-sm font-bold text-accent2 tracking-widest mb-1">第 ${n} 場</div>
564	        <div class="serif font-black text-3xl text-deep mb-1 flex items-center flex-wrap gap-2">
565	          <span>${d.label}</span>
566	          ${d.location ? `<span class="chip inline-flex items-center text-sm font-bold px-3 py-1 rounded-full align-middle"><i class="fa-solid fa-location-dot mr-1"></i>${d.location}</span>` : ''}
567	        </div>
568	        <div class="text-inksoft text-base mb-4">${isTBD ? '時間確認後公告' : `${t.start}–${t.end}（共${t.hours}小時）`}</div>
569	        ${(d.venue || d.address) ? `<div class="text-sm text-inksoft/80 mb-4 flex items-start gap-1.5"><i class="fa-solid fa-location-dot mt-0.5 text-accent2"></i><div>${d.venue ? `<span class="font-bold text-deep">${d.venue}</span>${d.address ? '｜' : ''}` : ''}${d.address || ''}${d.transport ? `<br><span class="text-xs text-inksoft/60">${d.transport}</span>` : ''}</div></div>` : ''}
570	        <div class="font-bold text-accent2 text-base mb-5">主題：${d.topic}</div>
571	        ${d.closed ? `<button disabled class="w-full py-3 rounded-full font-bold bg-gray-300 text-gray-500 cursor-not-allowed">已截止報名</button>` : `<button onclick="showRegisterModal('${sessionLabel}')" class="btn-primary w-full py-3 rounded-full font-bold">我要報名這場</button>`}
572	      `;
573	      grid.appendChild(card);
574	
575	      const opt = document.createElement('option');
576	      opt.value = sessionLabel;
577	      opt.textContent = sessionLabel;
578	      opt.dataset.slug = d.slug || '';
579	      select.appendChild(opt);
580	    });
581	  });
582	}
583	
584	// 依sessionLabel反查SESSION_DATES裡的場地資訊(地址/費用等)，跟buildSessions()同一套sessionLabel組法
585	function findSessionMeta(label) {
586	  for (const d of SESSION_DATES) {
587	    for (const s of d.slots) {
588	      const t = SLOTS[s];
589	      const isTBD = s === 'TBD';
590	      const sessionLabel = isTBD ? `${d.label} 時間確認後公告` : `${d.label} ${t.start}–${t.end}`;
591	      if (sessionLabel === label) return d;
592	    }
593	  }
594	  return null;
595	}
596	
597	function showRegisterModal(preselect) {
598	  const modal = document.getElementById('registerModal');
599	  modal.classList.remove('hidden'); modal.classList.add('flex');
600	  document.getElementById('registerForm').reset();
601	  const metaEl = document.getElementById('modalSessionMeta');
602	  if (preselect) {
603	    document.getElementById('regSession').value = preselect;
604	    document.getElementById('modalSessionLabel').textContent = '場次：' + preselect;
605	    const d = findSessionMeta(preselect);
606	    if (d && (d.venue || d.address || d.transport)) {
607	      metaEl.innerHTML = `${d.venue ? `<span class="font-bold">${d.venue}</span>${d.address ? '｜' : ''}` : ''}${d.address || ''}${d.transport ? `<br>${d.transport}` : ''}`;
608	      metaEl.classList.remove('hidden');
609	    } else {
610	      metaEl.innerHTML = ''; metaEl.classList.add('hidden');
611	    }
612	  } else {
613	    document.getElementById('modalSessionLabel').textContent = '選擇場次後送出，資料會直接帶到 LINE';
614	    metaEl.innerHTML = ''; metaEl.classList.add('hidden');
615	  }
616	}
